import pytest
import common

@pytest.mark.parametrize(
    "input, expected",
    [
        pytest.param("RRGGBBGRRGGBBG", 3),
        pytest.param("BBRGGRRGBBRGGBRGBBRRBRRRBGGRRRBGBGGBBRGGRRGBBRGGBRGBBRRBRRRBGGRRRBGBGG", 26),
        pytest.param("RGRGRBRBGBGRBGBRBRBRGRBRGRGRBRBRBRBRGBGBGRBRGRBRBRBRBRGBRBRGBGRGBRBRBGRBGBRBGBRBGBGRBRGRGBGBRBGRBRGR", 58),
    ],    
)
def test_count_flips(input, expected):
    flip_steps, letters_reversed, transformed = common.count_flips(input)    
    assert expected == flip_steps

#@pytest.mark.skip(reason="TODO: Ignore until implemented")
@pytest.mark.parametrize(
    "input, size, expected",
    [
        pytest.param("RRYGYBYG", 10, 1053),
        pytest.param("", 10, 24675718),
    ],    
)
def test_count_flips_using_repeating_input(input, size, expected):
    flip_steps, letters_reversed, transformed = common.count_flips(input * size)    
    assert expected == letters_reversed